@router.get("/monitoring/alerts/tenant/{tenant_slug}")
async def get_tenant_active_alerts(
    tenant_slug: str,
    alertmanager_client: AlertmanagerClient = Depends(get_am_client),
    current_user: User = Depends(get_current_user)
):
    if tenant_slug != current_user.tenant_slug and not current_user.is_ops_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized access to tenant alert incidents")

    alerts = await alertmanager_client.get_alerts(
        filter_expr=f'tenant="{tenant_slug}"'
    )
    return {"tenant": tenant_slug, "active_incidents": alerts}
